package cn.haiduo;
import java.util.*;
import java.math.BigDecimal;
import java.security.Principal;
import jakarta.servlet.http.HttpSession;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import cn.haiduo.audit.Audit;

@RestController @RequestMapping("/api/approvals") public class SkuApprovals {
 private final JdbcTemplate db;private final OperationsController scope;
 public SkuApprovals(JdbcTemplate db,OperationsController scope){this.db=db;this.scope=scope;}
 int grade(UUID t,String u){return db.queryForObject("select coalesce((select case when m.role='ADMIN' then 4 else coalesce(g.grade,2) end from membership m left join member_grade g on g.tenant_id=m.tenant_id and g.username=m.username where m.tenant_id=? and m.username=?),0)",Integer.class,t,u);}
 String role(UUID t,String u){return db.query("select role from membership where tenant_id=? and username=?",(rs,n)->rs.getString(1),t,u).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"成员已移除或无企业权限"));}
 void fail(HttpStatus status,String message){throw new ResponseStatusException(status,message);}
 boolean finance(String role){return Set.of("ADMIN","FINANCE").contains(role);}
 @GetMapping("/profile") Object profile(Principal p,HttpSession s){UUID t=scope.tenant(p,s);return Map.of("grade",grade(t,p.getName()),"role",role(t,p.getName()),"username",p.getName());}
 @GetMapping("/sku/{id}") Object sku(@PathVariable UUID id,Principal p,HttpSession s){UUID t=scope.tenant(p,s,"ADMIN","OPERATIONS","FINANCE");var rows=db.queryForList("select id,code,name,cost::text as cost,version from sku where tenant_id=? and id=?",t,id);if(rows.isEmpty())fail(HttpStatus.NOT_FOUND,"SKU不存在");return rows.getFirst();}
 @GetMapping Object list(Principal p,HttpSession s){UUID t=scope.tenant(p,s);return db.queryForList("select a.id,a.tenant_id,a.sku_id,a.applicant,a.expected_version,a.before_name,a.before_cost::text as before_cost,a.new_name,a.new_cost::text as new_cost,a.reason,a.status,a.reviewer,a.comment,a.created_at,a.expires_at,a.request_key,a.reviewed_at,k.code from sku_approval a join sku k on k.tenant_id=a.tenant_id and k.id=a.sku_id where a.tenant_id=? and (a.applicant=? or ? >=3) order by a.created_at desc limit 200",t,p.getName(),grade(t,p.getName()));}
 record Grade(String username,int grade){}
 @PostMapping("/grade") @Transactional Object grade(@RequestBody Grade r,Principal p,HttpSession s){UUID t=scope.tenant(p,s,"ADMIN");db.queryForObject("select id from tenant where id=? for no key update",UUID.class,t);scope.tenant(p,s,"ADMIN");if(r.grade()<1||r.grade()>3||p.getName().equals(r.username()))fail(HttpStatus.BAD_REQUEST,"仅可设置其他非管理员成员的1至3级职级");String role=role(t,r.username());if(role.equals("ADMIN"))fail(HttpStatus.CONFLICT,"管理员职级固定为4");if(r.grade()>grade(t,r.username())){Object proposal=BusinessWorkflows.propose(db,t,p.getName(),"MEMBER_GRADE",r.username(),r);if(proposal!=null)return proposal;}db.update("insert into member_grade values(?,?,?) on conflict(tenant_id,username) do update set grade=excluded.grade",t,r.username(),r.grade());new Audit(db).record(t,p.getName(),"MEMBER_GRADE_"+r.grade(),r.username());return Map.of("status","APPLIED");}
 record Edit(UUID skuId,long version,String name,String cost,String reason,UUID requestKey){Edit(UUID skuId,long version,String name,String cost,String reason){this(skuId,version,name,cost,reason,UUID.randomUUID());}}
 @PostMapping @Transactional Object submit(@RequestBody Edit r,Principal p,HttpSession s){UUID t=scope.tenant(p,s,"ADMIN","OPERATIONS","FINANCE");db.queryForObject("select id from tenant where id=? for no key update",UUID.class,t);scope.tenant(p,s,"ADMIN","OPERATIONS","FINANCE");if(r.name()==null||r.name().isBlank()||r.name().length()>200||r.cost()==null||!r.cost().matches("[0-9]{1,15}(\\.[0-9]{1,4})?")||r.reason()==null||r.reason().isBlank()||r.reason().length()>500)fail(HttpStatus.BAD_REQUEST,"请填写名称、有效成本及修改原因");if(r.requestKey()==null)fail(HttpStatus.BAD_REQUEST,"缺少请求幂等键");var prior=db.queryForList("select id,status,sku_id,new_name,new_cost,reason,expected_version from sku_approval where tenant_id=? and applicant=? and request_key=?",t,p.getName(),r.requestKey());if(!prior.isEmpty()){var saved=prior.getFirst();if(!saved.get("sku_id").equals(r.skuId())||!saved.get("new_name").equals(r.name().trim())||((BigDecimal)saved.get("new_cost")).compareTo(new BigDecimal(r.cost()))!=0||!saved.get("reason").equals(r.reason().trim())||((Number)saved.get("expected_version")).longValue()!=r.version())fail(HttpStatus.CONFLICT,"同一请求键不能用于不同修改");return Map.of("id",saved.get("id"),"status",saved.get("status"));}var rows=db.queryForList("select name,cost,version from sku where tenant_id=? and id=? for update",t,r.skuId());if(rows.isEmpty())fail(HttpStatus.NOT_FOUND,"SKU不存在");var old=rows.getFirst();if(((Number)old.get("version")).longValue()!=r.version())fail(HttpStatus.CONFLICT,"商品已修改，请刷新");boolean costChanged=((BigDecimal)old.get("cost")).compareTo(new BigDecimal(r.cost()))!=0;if(costChanged&&!finance(role(t,p.getName())))fail(HttpStatus.FORBIDDEN,"成本仅财务或管理员可申请修改");UUID id=UUID.randomUUID();boolean direct=grade(t,p.getName())>=2&&!costChanged;db.update("insert into sku_approval(id,tenant_id,sku_id,applicant,expected_version,before_name,before_cost,new_name,new_cost,reason,status,request_key) values(?,?,?,?,?,?,?,?,?,?,?,?)",id,t,r.skuId(),p.getName(),r.version(),old.get("name"),old.get("cost"),r.name().trim(),new BigDecimal(r.cost()),r.reason().trim(),direct?"APPLIED":"PENDING",r.requestKey());if(direct)apply(t,r.skuId(),r.name().trim(),new BigDecimal(r.cost()));new Audit(db).record(t,p.getName(),direct?"SKU_EDIT":"SKU_EDIT_REQUEST",id);return Map.of("id",id,"status",direct?"APPLIED":"PENDING");}
 void apply(UUID t,UUID sku,String name,BigDecimal cost){db.update("update sku set name=?,cost=?,version=version+1 where tenant_id=? and id=?",name,cost,t,sku);new Audit(db).record(t,"system","SKU_UPDATE",sku);}
 record Decision(String action,String comment){}
 @PostMapping("/{id}") @Transactional Object decide(@PathVariable UUID id,@RequestBody Decision r,Principal p,HttpSession s){UUID t=scope.tenant(p,s);db.queryForObject("select id from tenant where id=? for no key update",UUID.class,t);scope.tenant(p,s);var rows=db.queryForList("select *,expires_at<=now() as expired from sku_approval where tenant_id=? and id=? for update",t,id);if(rows.isEmpty())fail(HttpStatus.NOT_FOUND,"申请不存在");var a=rows.getFirst();String applicant=(String)a.get("applicant");if(r.action()==null||!Set.of("approve","reject","withdraw").contains(r.action()))fail(HttpStatus.BAD_REQUEST,"无效操作");if(r.action().equals("withdraw")){if(!applicant.equals(p.getName()))fail(HttpStatus.FORBIDDEN,"仅申请人可撤回");}else{if(applicant.equals(p.getName()))fail(HttpStatus.FORBIDDEN,"禁止自审");int reviewer=grade(t,p.getName()),sender=grade(t,applicant);if(reviewer<3||reviewer<sender)fail(HttpStatus.FORBIDDEN,"审批职级不足");boolean cost=((BigDecimal)a.get("before_cost")).compareTo((BigDecimal)a.get("new_cost"))!=0;if(cost&&!finance(role(t,p.getName())))fail(HttpStatus.FORBIDDEN,"成本修改需财务主管或管理员");if(!cost&&!Set.of("ADMIN","OPERATIONS").contains(role(t,p.getName())))fail(HttpStatus.FORBIDDEN,"需运营主管或管理员");if(r.action().equals("approve")&&!Set.of("ADMIN","OPERATIONS","FINANCE").contains(role(t,applicant)))fail(HttpStatus.FORBIDDEN,"申请人权限已撤回");}if(!a.get("status").equals("PENDING"))return Map.of("status",a.get("status"));String status;if(Boolean.TRUE.equals(a.get("expired")))status="EXPIRED";else if(r.action().equals("withdraw"))status="WITHDRAWN";else if(r.action().equals("reject")){if(r.comment()==null||r.comment().isBlank())fail(HttpStatus.BAD_REQUEST,"驳回须填写原因");status="REJECTED";}else{long version=db.queryForObject("select version from sku where tenant_id=? and id=? for update",Long.class,t,a.get("sku_id"));if(version!=((Number)a.get("expected_version")).longValue())status="STALE";else{if(((BigDecimal)a.get("before_cost")).compareTo((BigDecimal)a.get("new_cost"))!=0&&!finance(role(t,applicant)))fail(HttpStatus.FORBIDDEN,"申请人财务权限已撤回");apply(t,(UUID)a.get("sku_id"),(String)a.get("new_name"),(BigDecimal)a.get("new_cost"));status="APPLIED";}}if(r.comment()!=null&&r.comment().length()>500)fail(HttpStatus.BAD_REQUEST,"审批意见过长");db.update("update sku_approval set status=?,reviewer=?,comment=?,reviewed_at=now() where tenant_id=? and id=?",status,p.getName(),r.comment(),t,id);new Audit(db).record(t,p.getName(),"SKU_APPROVAL_"+status,id);return Map.of("status",status);}
}
